(()=>{
'use strict';
const A=window.KingdomArt,K=window.KingdomSim,baseTerrain=A.terrain,baseUnit=A.unit,baseMeasure=A.measure,baseBuilding=A.building;
const sizes={fishingboat:82,sloop:137,frigate:188,bombketch:145,transport:145};
function ellipse(c,x,y,rx,ry,fill,stroke){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke()}}
A.measure=kind=>{if(sizes[kind]){const img=A.tile(kind),w=sizes[kind];return {width:w,height:img?w*img.height/img.width:w}}return baseMeasure(kind)};
A.unit=(c,u,time,selected)=>{if(!sizes[u.kind])return baseUnit(c,u,time,selected);if(!A.loaded)return false;const img=A.tile(u.kind+(u.team?'-red':'')),w=sizes[u.kind],h=w*img.height/img.width,moving=u.path?.length>0,bob=Math.sin(time*1.7+u.id)*1.2;
ellipse(c,u.x,u.y+6,w*.32,w*.09,'#173e5233');if(moving)for(let i=0;i<3;i++){const p=(time*.5+i*.31)%1,x=u.x-(u.facing||1)*(w*.25+p*35);ellipse(c,x,u.y+6,7+p*14,2+p*3,null,`rgba(211,236,225,${(1-p)*.38})`)}if(selected){c.save();c.shadowColor='#c9e6c4';c.shadowBlur=8;ellipse(c,u.x,u.y+7,w*.38,w*.13,null,'#e0deac');c.restore()}
c.save();c.translate(u.x,u.y+bob+12);if(u.facing===-1)c.scale(-1,1);c.rotate(Math.sin(time*.8+u.id)*.012);if(u.flash>0)c.filter='brightness(1.8)';c.drawImage(img,-w/2,-h,w,h);c.restore();ellipse(c,u.x,u.y+8,3,2,u.team?'#e99779':'#a7d8ef');return true};
A.building=(c,b,time,selected,ghost)=>{const result=baseBuilding(c,b,time,selected,ghost);if(b.kind==='bath'&&selected&&!ghost){ellipse(c,b.x,b.y,170,85,'#a9d4c30c','#b3e1c659')}return result};
A.terrain=(c,W,H,isRiver)=>{baseTerrain(c,W,H,isRiver);let seed=49271;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};const shore=[];for(let x=0;x<=W;x+=8)shore.push([x,K.coast(x)]);
c.lineCap='round';c.lineJoin='round';c.strokeStyle='#737d5860';c.lineWidth=76;c.beginPath();shore.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.stroke();c.strokeStyle='#d3c59b';c.lineWidth=47;c.stroke();c.strokeStyle='#ded3ad';c.lineWidth=25;c.stroke();c.save();c.beginPath();c.moveTo(0,K.coast(0));for(const p of shore)c.lineTo(...p);c.lineTo(W,H);c.lineTo(0,H);c.closePath();c.clip();const depth=c.createLinearGradient(0,1880,0,H);depth.addColorStop(0,'#85b9ae');depth.addColorStop(.25,'#639e9c');depth.addColorStop(.6,'#3b7c87');depth.addColorStop(1,'#245a77');c.fillStyle=depth;c.fillRect(0,1850,W,H-1850);
for(let i=0;i<6000;i++){const x=rand()*W,y=1900+rand()*(H-1900);if(y<K.coast(x))continue;c.strokeStyle=i%4?'#d3ede314':'#163d5815';c.lineWidth=.6;c.beginPath();c.moveTo(x,y);c.bezierCurveTo(x+8,y-2,x+15,y+3,x+23+rand()*24,y);c.stroke()}c.strokeStyle='#d2ead67a';c.lineWidth=2;c.beginPath();shore.forEach(([x,y],i)=>i?c.lineTo(x,y+5):c.moveTo(x,y+5));c.stroke();c.restore();
for(let i=0;i<1700;i++){const x=rand()*W,y=K.coast(x)-rand()*25;c.fillStyle=i%3?'#a69a713d':'#ece1bc90';ellipse(c,x,y,rand()*1.8+.3,rand()*.8+.3,c.fillStyle)}
const tile=document.createElement('canvas');tile.width=380;tile.height=380;tile.getContext('2d').drawImage(A.ground(),0,0,380,380);const grass=c.createPattern(tile,'repeat');for(const island of K.islands){ellipse(c,island.x,island.y,island.rx+24,island.ry+20,'#cfc49b');ellipse(c,island.x,island.y,island.rx+11,island.ry+9,'#dfd2a6');ellipse(c,island.x,island.y,island.rx,island.ry,grass);const ruin=A.tile('ruins'),w=106,h=w*ruin.height/ruin.width;c.drawImage(ruin,island.x-w/2,island.y-h-4,w,h);for(let i=0;i<6;i++){const x=island.x+Math.sin(i*2)*120,y=island.y+Math.cos(i*3)*62;ellipse(c,x,y,5,2,'#a3a78b')}}
};
const atmosphere=A.atmosphere;A.atmosphere=(c,time,W,H)=>{atmosphere(c,time,W,H);for(let i=0;i<95;i++){const x=(i*137.9+time*7)%W,y=K.coast(x)+60+(i*113)%(Math.max(140,H-K.coast(x)-100));if(!K.isOcean(x,y))continue;const p=(time*.25+i*.13)%1;c.strokeStyle=`rgba(201,230,219,${Math.sin(p*Math.PI)*.1})`;c.lineWidth=.8;c.beginPath();c.moveTo(x-10,y);c.quadraticCurveTo(x,y-3,x+18,y);c.stroke()}};
})();
